class WS:
    def __init__(self,url):
        u=urllib.parse.urlparse(url); self.sock=socket.create_connection((u.hostname,u.port or 80),timeout=10); self.sock.settimeout(10)
        key=base64.b64encode(secrets.token_bytes(16)).decode(); path=u.path or '/'
        if u.query: path+='?'+u.query
        req=(f'GET {path} HTTP/1.1\r\nHost: {u.hostname}:{u.port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n').encode()
        self.sock.sendall(req); buf=b''
        while b'\r\n\r\n' not in buf: buf+=self.sock.recv(4096)
        if b' 101 ' not in buf.split(b'\r\n',1)[0]: die('websocket handshake failed '+repr(buf[:300]))
        self.seq=0; self.events=[]
    def send_text(self,s):
        data=s.encode(); n=len(data); mask=secrets.token_bytes(4); head=bytearray([0x81])
        if n<126: head.append(0x80|n)
        elif n<65536: head.append(0x80|126); head.extend(struct.pack('!H',n))
        else: head.append(0x80|127); head.extend(struct.pack('!Q',n))
        masked=bytes(b^mask[i%4] for i,b in enumerate(data)); self.sock.sendall(bytes(head)+mask+masked)
    def recv_frame(self):
        def exact(n):
            out=b''
            while len(out)<n:
                c=self.sock.recv(n-len(out))
                if not c: raise EOFError
                out+=c
            return out
        h=exact(2); op=h[0]&0x0f; n=h[1]&0x7f; masked=bool(h[1]&0x80)
        if n==126:n=struct.unpack('!H',exact(2))[0]
        elif n==127:n=struct.unpack('!Q',exact(8))[0]
        mask=exact(4) if masked else None; data=exact(n)
        if masked:data=bytes(b^mask[i%4] for i,b in enumerate(data))
        if op==9: self.send_control(0xA,data); return self.recv_frame()
        if op==8: raise EOFError
        return op,data
    def send_control(self,op,data=b''):
        n=len(data); mask=secrets.token_bytes(4); head=bytes([0x80|op,0x80|n]); masked=bytes(b^mask[i%4] for i,b in enumerate(data)); self.sock.sendall(head+mask+masked)
    def call(self,method,params=None,timeout=15):
        self.seq+=1; i=self.seq; self.send_text(json.dumps({'id':i,'method':method,'params':params or {}},separators=(',',':')))
        deadline=time.time()+timeout
        while time.time()<deadline:
            op,data=self.recv_frame()
            if op!=1: continue
            m=json.loads(data)
            if m.get('id')==i:
                if 'error' in m: die(f'CDP {method}: {m["error"]}')
                return m.get('result',{})
            if 'method' in m:self.events.append(m)
        die('CDP timeout '+method)
    def drain(self,seconds=.4):
        end=time.time()+seconds; old=self.sock.gettimeout(); self.sock.settimeout(.05)
        try:
            while time.time()<end:
                try:
                    op,data=self.recv_frame()
                    if op==1:
                        m=json.loads(data)
                        if 'method' in m:self.events.append(m)
                except socket.timeout: pass
        finally:self.sock.settimeout(old)

def http_json(url,method='GET'):
    req=urllib.request.Request(url,method=method)
    with urllib.request.urlopen(req,timeout=10) as r:return json.loads(r.read())

def ev(ws,expr,await_promise=False):
    r=ws.call('Runtime.evaluate',{'expression':expr,'returnByValue':True,'awaitPromise':await_promise,'userGesture':True})
    if r.get('exceptionDetails'): die('JS exception '+json.dumps(r['exceptionDetails'])[:1000])
    return r.get('result',{}).get('value')

def wait_ready(ws,timeout=20):
    end=time.time()+timeout
    while time.time()<end:
        try:
            if ev(ws,'document.readyState')=='complete' and ev(ws,"typeof phase16bContinuityStore !== 'undefined'") is True:return
        except Exception: pass
        time.sleep(.2)
    die('page/app not ready')

def run_turn(ws,text):
    js=f'''(()=>{{
      const text={json.dumps(text)};
      const requestId=nextPhase14RequestId();
      const requestContext=speechContextVersion(session.view);
      try{{phase15LongitudinalExtension?.notifyUserIngress?.({{requestId,text}})}}catch(_e){{}}
      const turn=phase14Coordinator.handleTurn({{requestId,text,origin:'normal'}});
      if(turn?.completion) return {{requestId,async:true,route:turn.route,message:turn.message||'',extensionTrace:turn.extensionTrace||null}};
      let shown=null;
      if(turn?.route==='CONSUMED'){{
        shown=presentPhase14Result(turn.message,{{safety:!!turn.safety,companionTurn:turn.companionTurn}});
        acknowledgePhase16BPresentation(requestId,turn.message,turn.companionTurn,requestContext,shown);
      }}
      return {{requestId,route:turn?.route||null,message:turn?.message||'',shown,extensionTrace:turn?.extensionTrace||null,
        capture:phase15LongitudinalExtension?.inspectContinuity?.().capture||null,
        store:phase16bContinuityStore?.readStrict?.()||null}};
    }})()'''
    return ev(ws,js)

